import decimal
from decimal import Decimal, getcontext
getcontext().prec = 80

def f(x):
    return x**3 + Decimal('4')*x**2 - Decimal('3')*x + Decimal('8')

def fp(x):
    return Decimal('3')*x**2 + Decimal('8')*x - Decimal('3')

def round4(x):
    # round to 4 decimal places, using ROUND_HALF_UP maybe
    return x.quantize(Decimal('0.0001'), rounding=decimal.ROUND_HALF_UP)

x = Decimal('-5')
history = [x]
for i in range(20):
    x_new = x - f(x)/fp(x)
    history.append(x_new)
    x = x_new

for i, val in enumerate(history):
    print(i, val, round4(val))

# find smallest n (starting from 0?) where round4(x_n) == round4(x_{n+1})
for n in range(len(history)-1):
    if round4(history[n]) == round4(history[n+1]):
        print('first n where rounded equal:', n)
        break
